const gravekeeperSheet=new Image();gravekeeperSheet.assetSrc='assets/gravekeeper-v2.png';
function beginGravekeeper(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'gravekeeperBurial',bespoke:true,windup:1.8,origin:{x:e.x,y:e.y},target:{x:p.x,y:p.y},lastDodge:cd[3]||0,counter:false,fired:false};}
const gravekeeperAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r10e2')return gravekeeperAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='gravekeeperBurial'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=270&&clear){beginGravekeeper(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,80*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 let dodge=cd[3]||0;if(!a.fired&&!a.counter&&e.elapsed<=1.2&&dodge>a.lastDodge+.001&&dist(a.origin,p)<=500&&lineClear(a.origin,p)){a.target={x:p.x,y:p.y};a.counter=true;a.windup=Math.max(1.8,e.elapsed+.65);playSound('impact',e.x,e.y);}a.lastDodge=dodge;
 if(!a.fired&&e.elapsed>=a.windup){a.fired=true;e.struck=true;if(dist(a.target,p)<=70&&lineClear(a.origin,a.target)&&lineClear(a.target,p))hurt(a.counter?84:60);playSound('impact',a.target.x,a.target.y);}
 if(e.elapsed>=a.windup+1){e.attack=null;e.state='idle';e.t=2.8;}
};
const gravekeeperDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r10e2'||!gravekeeperSheet.complete||!gravekeeperSheet.naturalWidth||!gravekeeperSheet.naturalHeight)return gravekeeperDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0),a=e.attack;if(e.hp<=0)f={row:2,col:3};else if(a?.pattern==='gravekeeperBurial')f={row:2,col:e.elapsed<1.2?0:e.elapsed<a.windup?1:e.elapsed<a.windup+.25?2:3};let q=project(e.x,e.y),sw=gravekeeperSheet.naturalWidth/4,sh=gravekeeperSheet.naturalHeight/3,w=230,h=w*sh/sw,anchor=[[.9,.9,.89,.9],[.85,.85,.85,.85],[.84,.84,.84,.84]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,gravekeeperSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(gravekeeperSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const gravekeeperSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r10e2'?175:gravekeeperSizeBase(e);
const gravekeeperGroundBase=drawGroundEffects;drawGroundEffects=()=>{gravekeeperGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r10e2'):enemies)){let a=e.attack;if(e.species!=='r10e2'||e.hp<=0||a?.pattern!=='gravekeeperBurial'||e.elapsed>a.windup+.3||!visibleAt(a.target.x,a.target.y))continue;let color=a.fired?'#f4ddff':a.counter?'#ffb883':'#bf9bda';groundRing(a.target.x,a.target.y,70,color,3);if(!a.fired){groundRing(a.target.x,a.target.y,70*Math.min(1,e.elapsed/a.windup),color,1);if(e.elapsed<1.2&&!a.counter)groundRing(e.x,e.y,28,'#d7be8c',2);}else{let q=project(a.target.x,a.target.y);ctx.save();ctx.strokeStyle=color;ctx.lineWidth=4;for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(q.x+i*24,q.y+8);ctx.lineTo(q.x+i*24,q.y-45-Math.abs(i)*8);ctx.stroke();}ctx.restore();}}};
if(typeof registerDirectEnemy==='function')registerDirectEnemy('r10e2',animateEnemy,drawRegionEnemy);
